const items = $input.all();
const output = [];

for (const item of items) {

  let numero = String(item.json.Telefone || "").replace(/\D/g, "");

  if (!numero) continue;

  let com9 = numero;
  let sem9 = numero;

  if (numero.startsWith("55")) {

    // se já tiver o 9 após DDD
    if (numero.length === 13 && numero[4] === "9") {
      sem9 = numero.slice(0,4) + numero.slice(5);
      com9 = numero;
    }

    // se NÃO tiver o 9
    else if (numero.length === 12) {
      com9 = numero.slice(0,4) + "9" + numero.slice(4);
      sem9 = numero;
    }
  }

  // item com 9
  output.push({
    json: {
      ...item.json,
      Telefone: com9
    }
  });

  // item sem 9
  output.push({
    json: {
      ...item.json,
      Telefone: sem9
    }
  });

}

return output;

const items = $input.all();

function normalizeNumber(num) {
  return String(num || "").replace(/\D/g, "");
}

function generateVariations(phone) {
  let number = normalizeNumber(phone);

  if (!number.startsWith("55")) return {};

  const ddi = "55";
  const ddd = number.slice(2, 4);
  let rest = number.slice(4);

  let telefone_com_9;
  let telefone_sem_9;

  // Já tem 9
  if (number.length === 13 && rest.startsWith("9")) {
    telefone_com_9 = number;
    telefone_sem_9 = ddi + ddd + rest.slice(1);
  } 
  // Não tem 9
  else if (number.length === 12) {
    telefone_sem_9 = number;
    telefone_com_9 = ddi + ddd + "9" + rest;
  }

  return { telefone_com_9, telefone_sem_9 };
}

return items.map(item => {
  const body = item.json.body;

  const inbox_id = body.inbox_id;

  const phone =
    body?.meta?.sender?.phone_number ||
    body?.contact_inbox?.source_id ||
    "";

  const { telefone_com_9, telefone_sem_9 } = generateVariations(phone);

  return {
    json: {
      inbox_id,
      telefone_com_9,
      telefone_sem_9
    }
  };
});

